What it is. New in 2025. The app does not plan for errors: it fails open (grants access when a check crashes), leaks stack traces, or leaves half-finished work behind. OWASP maps CWEs such as "CWE-209 Error messages containing sensitive information" and "CWE-636 Not failing securely".
# a10_errors.py — fail closed, and never show internals
import logging, uuid
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
log = logging.getLogger("app")
app = FastAPI()
def permission_service(user: str, doc: int) -> bool:
raise TimeoutError("policy server did not answer") # simulate an outage
def can_delete_bad(user: str, doc: int) -> bool:
try:
return permission_service(user, doc)
except Exception:
return True # FAIL OPEN: an outage lets everyone delete
def can_delete(user: str, doc: int) -> bool:
try:
return permission_service(user, doc)
except Exception:
log.exception("permission check failed")
return False # FAIL CLOSED: deny when unsure
@app.exception_handler(Exception)
async def unhandled(request: Request, exc: Exception):
error_id = uuid.uuid4().hex[:8] # the user reports this id; the log has the details
log.error("error %s on %s", error_id, request.url.path, exc_info=exc)
return JSONResponse({"error": "internal error", "id": error_id}, status_code=500)
@app.delete("/files/{doc}")
def delete_file(doc: int):
if not can_delete("ada", doc):
return

